    /// The distinct arrangements of a currency symbol, a sign and the digits, in the order a locale's
    /// record counts them.
    @_optimize(none) private static func makePatterns() -> [MoneyFormatPattern] {
        [
            MoneyFormatPattern(
            positive: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency]),
            negative: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency]),
            accountingNegative: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency])
        ),
            MoneyFormatPattern(
            positive: MoneyFormatAffixes(prefix: [.sign, .currency, .currencySpacing], suffix: []),
            negative: MoneyFormatAffixes(prefix: [.sign, .currency, .currencySpacing], suffix: []),
            accountingNegative: MoneyFormatAffixes(prefix: [.literal("("), .currency, .currencySpacing], suffix: [.literal(")")])
        ),
            MoneyFormatPattern(
            positive: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency]),
            negative: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency]),
            accountingNegative: MoneyFormatAffixes(prefix: [.literal("(")], suffix: [.currencySpacing, .currency, .literal(")")])
        ),
            MoneyFormatPattern(
            positive: MoneyFormatAffixes(prefix: [.sign, .currency, .currencySpacing], suffix: []),
            negative: MoneyFormatAffixes(prefix: [.sign, .currency, .currencySpacing], suffix: []),
            accountingNegative: MoneyFormatAffixes(prefix: [.sign, .currency, .currencySpacing], suffix: [])
        ),
        ]
    }

    /// The distinct arrangements of a currency's full name beside the digits, in the same order.
    @_optimize(none) private static func makeFullNamePatterns() -> [FullNameLayout] {
        [
            FullNameLayout(other: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency])),
            FullNameLayout(other: MoneyFormatAffixes(prefix: [.sign], suffix: [.currency])),
            FullNameLayout(other: MoneyFormatAffixes(prefix: [.sign], suffix: [.literal(" de "), .currency]), byCategory: [.one: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency]), .few: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency])]),
            FullNameLayout(other: MoneyFormatAffixes(prefix: [.currency, .sign], suffix: [])),
            FullNameLayout(other: MoneyFormatAffixes(prefix: [.currency, .currencySpacing, .sign], suffix: []), byCategory: [.one: MoneyFormatAffixes(prefix: [.sign], suffix: [.currencySpacing, .currency])]),
        ]
    }

    /// Each language's plural rules, in the order CLDR resolves them. A language with no rule for a
    /// category takes `other`, which never carries one.
    package static let pluralRules: [String: [PluralCategory: PluralRule]] = makePluralRules()
    @_optimize(none) private static func makePluralRules() -> [String: [PluralCategory: PluralRule]] {
        [
        "en": [
            .one: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .integerPart, comparison: .equals(NonEmpty(PluralRange(1)))), [PluralRelation(operand: .fractionDigitCount, comparison: .equals(NonEmpty(PluralRange(0))))]))),
        ],
        "de": [
            .one: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .integerPart, comparison: .equals(NonEmpty(PluralRange(1)))), [PluralRelation(operand: .fractionDigitCount, comparison: .equals(NonEmpty(PluralRange(0))))]))),
        ],
        "fr": [
            .one: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .integerPart, comparison: .equals(NonEmpty(PluralRange(0), [PluralRange(1)])))))),
            .many: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .compactExponent, comparison: .equals(NonEmpty(PluralRange(0)))), [PluralRelation(operand: .integerPart, comparison: .notEquals(NonEmpty(PluralRange(0)))), PluralRelation(operand: .integerPart, modulus: 1000000, comparison: .equals(NonEmpty(PluralRange(0)))), PluralRelation(operand: .fractionDigitCount, comparison: .equals(NonEmpty(PluralRange(0))))]), [NonEmpty(PluralRelation(operand: .compactExponent, comparison: .notEquals(NonEmpty(PluralRange(0 ... 5)))))])),
        ],
        "ja": [:],
        "sw": [
            .one: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .integerPart, comparison: .equals(NonEmpty(PluralRange(1)))), [PluralRelation(operand: .fractionDigitCount, comparison: .equals(NonEmpty(PluralRange(0))))]))),
        ],
        "si": [
            .one: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .absoluteValue, comparison: .equals(NonEmpty(PluralRange(0), [PluralRange(1)])))), [NonEmpty(PluralRelation(operand: .integerPart, comparison: .equals(NonEmpty(PluralRange(0)))), [PluralRelation(operand: .fractionDigits, comparison: .equals(NonEmpty(PluralRange(1))))])])),
        ],
        "ro": [
            .one: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .integerPart, comparison: .equals(NonEmpty(PluralRange(1)))), [PluralRelation(operand: .fractionDigitCount, comparison: .equals(NonEmpty(PluralRange(0))))]))),
            .few: PluralRule(orOfAndGroups: NonEmpty(NonEmpty(PluralRelation(operand: .fractionDigitCount, comparison: .notEquals(NonEmpty(PluralRange(0))))), [NonEmpty(PluralRelation(operand: .absoluteValue, comparison: .equals(NonEmpty(PluralRange(0))))), NonEmpty(PluralRelation(operand: .absoluteValue, comparison: .notEquals(NonEmpty(PluralRange(1)))), [PluralRelation(operand: .absoluteValue, modulus: 100, comparison: .equals(NonEmpty(PluralRange(1 ... 19))))])])),
        ],
        ]
    }
}